import sys
import time
from concurrent.futures import ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Check every element of xs in parallel using a thread pool.

    Returns the checked values in input order if all pass. If any element is
    bad, raises the Bad of the lowest-index bad element, regardless of which
    thread finishes first.
    """
    with ThreadPoolExecutor(max_workers=max(1, min(32, len(xs)))) as ex:
        futures = [ex.submit(check, x) for x in xs]
        # Consume results in input order: the first future that raised is the
        # lowest-index bad element, no matter which thread finished first.
        return [f.result() for f in futures]


def test_all_even_ok_preserves_order() -> None:
    xs = [2, 4, 6, 8, 10, 0, -2]
    assert all_even(xs) == xs


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_single_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 4, 5, 6])
    assert ei.value.n == 5


def test_lowest_index_not_lowest_value() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 7, 4, 3])
    assert ei.value.n == 7


def test_lowest_index_wins_even_if_it_finishes_last(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    real = check

    def slow_check(x: int) -> int:
        if x == 1:
            time.sleep(0.3)
        return real(x)

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)
    with pytest.raises(Bad) as ei:
        all_even([2, 1, 3, 5, 4])
    assert ei.value.n == 1


def test_all_bad_lowest_index_wins_with_reversed_timing(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    real = check

    def timed_check(x: int) -> int:
        # Earlier elements take longer, so later ones fail first.
        time.sleep(0.05 * (10 - x))
        return real(x)

    monkeypatch.setattr(sys.modules[__name__], "check", timed_check)
    with pytest.raises(Bad) as ei:
        all_even([1, 3, 5, 7])
    assert ei.value.n == 1


def test_uses_thread_pool_for_parallelism(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    real = check

    def slow_check(x: int) -> int:
        time.sleep(0.2)
        return real(x)

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)
    xs = [2, 4, 6, 8]
    start = time.monotonic()
    assert all_even(xs) == xs
    elapsed = time.monotonic() - start
    assert elapsed < 0.2 * len(xs) * 0.75

